module.exports = async function (context, eventHubMessages) {
  const enriched = eventHubMessages.map(m => ({
    deviceId: m.properties?.deviceId || m.systemProperties['iothub-connection-device-id'],
    timestamp: m.body?.timestamp || new Date().toISOString(),
    tempC: m.body?.tempC
  }));
  context.log(`Enriched ${enriched.length} messages`);
  // Pseudo: insert into Azure SQL using a managed identity
  return enriched;
}
